import{_ as e,o as r,c as d,ah as a}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Overview","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/overview.md","filePath":"src/en/guide/overview.md"}'),n={name:"en/guide/overview.md"};function o(i,t,s,c,l,u){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p><strong>Kura</strong> is the administrative and financial platform of <strong>NextBoxx</strong>, edPage group&#39;s training organisation. It centralises the catalogue, cohorts, candidatures, enrolments, billing, certification and payouts. It is the single source of truth for everything that is not pedagogical.</p><h2 id="the-nextboxx-ecosystem" tabindex="-1">The NextBoxx ecosystem <a class="header-anchor" href="#the-nextboxx-ecosystem" aria-label="Permalink to &quot;The NextBoxx ecosystem&quot;">​</a></h2><p>The business rests on four distinct building blocks:</p><table tabindex="0"><thead><tr><th>Building block</th><th>Role</th></tr></thead><tbody><tr><td><strong>NextBoxx website</strong></td><td>Public storefront: catalogue, candidature submission, event registration. Stateless, it sends data to Kura through an API.</td></tr><tr><td><strong>Kura</strong></td><td>Administrative and financial backbone: identity, admission, cohorts, enrolments, billing, certification, payouts, documents. This guide.</td></tr><tr><td><strong>Sève</strong></td><td>Rebranded Moodle LMS: contents, virtual classrooms, assessments, attendance, coaching.</td></tr><tr><td><strong>Parcours Canopé</strong></td><td>Status and community of certified alumni.</td></tr></tbody></table><p>Kura is Sève&#39;s <strong>identity provider</strong> (OAuth2/OpenID Connect): a NextBoxx account grants access to Sève through SSO, with no Moodle password. Sève stores no financial or contractual data and only sends aggregated data back to Kura (attendance, completion, grades).</p><h2 id="guiding-principles" tabindex="-1">Guiding principles <a class="header-anchor" href="#guiding-principles" aria-label="Permalink to &quot;Guiding principles&quot;">​</a></h2><ul><li><strong>One account per person</strong>, deduplicated by email; roles accumulate and accounts are never recreated.</li><li><strong>Kura decides, Sève executes.</strong> No administrative or financial decision (opening a cohort, validating an enrolment, billing, certification) happens in Sève.</li><li><strong>The public website is stateless.</strong> An accepted candidature or registration is copied back to the website CMS, never the other way round.</li><li><strong>Notifications decide nothing.</strong> They remind and alert; decisions remain human, except for the automatic transitions defined by the business rules.</li><li><strong>Amounts in FCFA</strong>, stored as <code>DECIMAL(12,2)</code>, expressed excluding tax.</li><li><strong>Traceability</strong>: actions by privileged accounts on accounts and roles are logged.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>The <strong>core</strong> covers modules 1 to 18, module 29 (NextBoxx account), which is cross-cutting, and module 32 (Generated documents), required for welcome booklets, agreements, invoices and certificates.</p><p>The <strong>extended activities</strong> (modules 19 to 28, 30, 31 and 33) extend the core: B2B training on quotation, events, company requests and recruitment, event funding, L&#39;Éclosion incubation and technology partnerships.</p><table tabindex="0"><thead><tr><th>#</th><th>Module</th><th>Block</th></tr></thead><tbody><tr><td>1</td><td>Training catalogue</td><td>Core</td></tr><tr><td>2</td><td>Cohort management</td><td>Core</td></tr><tr><td>3</td><td>Enrolments and learner file</td><td>Core</td></tr><tr><td>4</td><td>Attendance tracking (Kura view)</td><td>Core</td></tr><tr><td>5</td><td>Assessments and results (Kura view)</td><td>Core</td></tr><tr><td>6</td><td>Certification (certificate, partial attestation)</td><td>Core</td></tr><tr><td>7</td><td>NextBoxx billing (30/40/30, online payment)</td><td>Core</td></tr><tr><td>8</td><td>Communication (announcements, reminders)</td><td>Core</td></tr><tr><td>9</td><td>Reporting</td><td>Core</td></tr><tr><td>10</td><td>Trainer and coach remuneration</td><td>Core</td></tr><tr><td>11</td><td>Business referrer commissions</td><td>Core</td></tr><tr><td>12</td><td>Marketing partners</td><td>Core</td></tr><tr><td>13</td><td>Dashboard — session postponement decision</td><td>Core</td></tr><tr><td>14</td><td>Sève integration</td><td>Core</td></tr><tr><td>15</td><td>Direction dashboard</td><td>Core</td></tr><tr><td>16</td><td>Funder area (company)</td><td>Core</td></tr><tr><td>17</td><td>Electronic signature</td><td>Core</td></tr><tr><td>18</td><td>Candidature management and admission (including QCM test)</td><td>Core</td></tr><tr><td>19</td><td>B2B training on quotation</td><td>Extended</td></tr><tr><td>20–22</td><td>Events (creation, registrations, funding)</td><td>Extended</td></tr><tr><td>23–26</td><td>Company requests, matching and recruitment</td><td>Extended</td></tr><tr><td>27–28</td><td>Event funding and event funder area</td><td>Extended</td></tr><tr><td>29</td><td>NextBoxx account (one account, several roles)</td><td>Cross-cutting</td></tr><tr><td>30–31</td><td>L&#39;Éclosion incubation and participations</td><td>Extended</td></tr><tr><td>32</td><td>Generated documents</td><td>Core</td></tr><tr><td>33</td><td>Technology partnerships</td><td>Extended</td></tr></tbody></table><h2 id="key-figures" tabindex="-1">Key figures <a class="header-anchor" href="#key-figures" aria-label="Permalink to &quot;Key figures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figure</th><th>Value</th></tr></thead><tbody><tr><td>Programmes at launch</td><td>40, in 3 categories</td></tr><tr><td>Yearly intakes</td><td>4 promotions: Baobab (September), Iroko (December), Acacia (March), Karité (June)</td></tr><tr><td>Cohort capacity</td><td>15 learners</td></tr><tr><td>Simultaneous virtual classrooms</td><td>10 at most, 15 participants per classroom</td></tr><tr><td>Instalments</td><td>3 tranches: 30% on signature, 40% mid-course, 30% at the end</td></tr><tr><td>Admission test pass mark</td><td>60%, i.e. 6 correct answers out of 10</td></tr><tr><td>Absence alert threshold</td><td>30% of the total hours</td></tr><tr><td>Business referrer commission</td><td>5% of amounts collected</td></tr><tr><td>Retention of invoices and agreements</td><td>10 years (OHADA)</td></tr></tbody></table><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/kura-guide/en/guide/getting-started.html">Getting started</a> — install and run Kura locally.</li><li><a href="/kura-guide/en/guide/architecture.html">Architecture</a> — stack, code structure and data model.</li><li><a href="/kura-guide/en/guide/roles.html">Accounts and roles</a> — who can do what.</li><li><a href="/kura-guide/en/guide/learner-journey.html">Learner journey</a> — from candidature to Parcours Canopé.</li><li><a href="/kura-guide/en/guide/core-modules.html">Core modules</a> — the day-to-day business rules.</li></ul>',16)])])}const m=e(n,[["render",o]]);export{g as __pageData,m as default};
